// Meta signs each delivery with the app secret; anything else may be someone pretending to be a customer.
const crypto = require('crypto');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const sent = String($json.headers['x-hub-signature-256'] ?? '');
const expected = 'sha256=' + crypto.createHmac('sha256', $env.WHATSAPP_APP_SECRET).update(raw).digest('hex');
const valid = sent.length === expected.length && crypto.timingSafeEqual(Buffer.from(sent), Buffer.from(expected));
return [{ json: { valid, body: valid ? JSON.parse(raw.toString('utf8')) : null } }];

// One item per customer message. Delivery and read receipts carry no messages and stop here.
const MAX_TEXT_LENGTH = 4096;
const SKIPPED_TYPES = new Set(['reaction']);
const RECEIPT_TYPES = new Set(['image/jpeg', 'image/png', 'application/pdf']); // what the API takes (PAY-02)
const items = [];
for (const entry of $json.body?.entry ?? []) {
  for (const change of entry.changes ?? []) {
    if (change.field !== 'messages') continue;
    const value = change.value ?? {};
    for (const message of value.messages ?? []) {
      if (SKIPPED_TYPES.has(message.type)) continue;
      // A tapped reply button or list row reads as if the customer had typed its title.
      const tapped = message.interactive?.button_reply ?? message.interactive?.list_reply;
      const media = message.image ?? message.document ?? null;
      const mimeType = String(media?.mime_type ?? '').split(';')[0].trim();
      const text = message.text?.body ?? tapped?.title ?? media?.caption ?? '';
      items.push({
        json: {
          phoneNumberId: String(value.metadata?.phone_number_id ?? ''),
          waId: String(message.from),
          phone: '+' + String(message.from).replace(/\D/g, ''),
          messageId: String(message.id),
          type: String(message.type),
          text: text.trim().slice(0, MAX_TEXT_LENGTH),
          receiptMediaId: media && RECEIPT_TYPES.has(mimeType) ? String(media.id) : null,
          tapId: tapped?.id ?? null,
        },
      });
    }
  }
}
return items;

// Everything the agent knows without a tool, as text for its prompt (T36).
const TIME_ZONE = 'Asia/Colombo';
const BOOKING_HORIZON_DAYS = 30; // D-06
const DATES_LISTED = 8; // today and the next 7 days
const SPORTS = { FUTSAL_COURT: 'Futsal court', TABLE_TENNIS_TABLE: 'Table tennis table', POOL_TABLE: 'Pool table' };
const DAY_NAMES = ['', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const LISTS = ['Find Venues', 'Find Resources', 'Find Price Rules', 'Find Plans'];

const message = $('Read Messages').item.json;
const tenantId = $('Find Tenant').item.json.data.content[0].tenantId;
const tenantName = $('Read Tenant').item.json.data.name;
const venues = $('Find Venues').item.json.data.content;
const resources = $('Find Resources').item.json.data.content;
const priceRules = $('Find Price Rules').item.json.data.content;
const plans = $('Find Plans').item.json.data.content;
const customer = $json.data.content[0] ?? null;

// "+94771234567" reads as "077 123 4567" in Sri Lanka.
const localPhone = (phone) =>
  phone.startsWith('+94') && phone.length === 12
    ? '0' + phone.slice(3, 5) + ' ' + phone.slice(5, 8) + ' ' + phone.slice(8)
    : phone;
const money = (m) => m.currency + ' ' + (m.amount / 100).toLocaleString('en-US', { maximumFractionDigits: 2 });
const clock = (hhmm) => {
  if (hhmm === '24:00') return 'midnight';
  const [h, m] = hhmm.split(':').map(Number);
  return (h % 12 || 12) + ':' + String(m).padStart(2, '0') + (h < 12 ? ' am' : ' pm');
};
// [1,2,3,4,5,7] reads as "Mon–Fri, Sun".
const dayList = (weekdays) => {
  const sorted = [...weekdays].sort((a, b) => a - b);
  if (sorted.length === 7) return 'every day';
  const runs = [];
  for (const day of sorted) {
    const run = runs.at(-1);
    if (run && run.at(-1) === day - 1) run.push(day);
    else runs.push([day]);
  }
  return runs
    .map((run) => (run.length > 2 ? DAY_NAMES[run[0]] + '–' + DAY_NAMES[run.at(-1)] : run.map((d) => DAY_NAMES[d]).join(', ')))
    .join(', ');
};
const hoursOf = (venue) => {
  const byHours = new Map();
  for (const day of venue.openingHours) {
    const hours = clock(day.opens) + ' to ' + clock(day.closes);
    byHours.set(hours, [...(byHours.get(hours) ?? []), day.weekday]);
  }
  const open = [...byHours].map(([hours, days]) => dayList(days) + ', ' + hours);
  const closed = [1, 2, 3, 4, 5, 6, 7].filter((d) => !venue.openingHours.some((h) => h.weekday === d));
  if (closed.length > 0) open.push('closed ' + dayList(closed));
  return open.length > 0 ? open.join('; ') : 'no opening hours set';
};
const lengthOf = (plan) =>
  plan.lengthCount + ' ' + (plan.lengthUnit === 'DAYS' ? 'day' : 'month') + (plan.lengthCount === 1 ? '' : 's');
const durationOf = (minutes) => (minutes % 60 === 0 ? minutes / 60 + ' hours' : minutes + ' minutes').replace(/^1 hours/, '1 hour');
const paymentOf = (venue) => {
  if (venue.payAtVenue) return 'Pay at Venue: online bookings are confirmed straight away; customers pay everything at the venue.';
  const advance = venue.advancePercent === 100 ? 'The full price' : 'An Advance of ' + venue.advancePercent + '% of the price';
  const rest = venue.advancePercent === 100 ? '' : ' The rest is paid at the venue.';
  return advance + ' is paid by bank transfer within ' + durationOf(venue.paymentTimeLimitMinutes) +
    ' of booking online, by sending a photo of the Transfer Receipt; otherwise the booking expires.' + rest;
};

// Dates on Sri Lankan clocks: noon UTC on the local date keeps day arithmetic clear of midnight.
const now = new Date();
const localDate = (date) => date.toLocaleDateString('en-CA', { timeZone: TIME_ZONE });
const addDays = (isoDate, days) => {
  const date = new Date(isoDate + 'T12:00:00Z');
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
};
const longDate = (isoDate) =>
  new Date(isoDate + 'T12:00:00Z').toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const today = localDate(now);
const timeNow = now.toLocaleTimeString('en-GB', { timeZone: TIME_ZONE, hour: 'numeric', minute: '2-digit', hour12: true });
const dates = Array.from({ length: DATES_LISTED }, (_, i) => addDays(today, i));
const dayWords = ['today', 'tomorrow'];

const facts = [
  'Now: ' + longDate(today) + ', ' + timeNow + ' (Sri Lankan time).',
  'Dates:',
  ...dates.map((date, i) => '• ' + date + ': ' + longDate(date) + (dayWords[i] ? ' (' + dayWords[i] + ')' : '')),
  'Customers can book from now up to ' + longDate(addDays(today, BOOKING_HORIZON_DAYS)) + ' (' + BOOKING_HORIZON_DAYS + ' days ahead).',
  '',
  customer ? 'The customer: ' + customer.name + ', a known customer.' : 'The customer: new; their name is not known yet.',
];

if (venues.length === 0) facts.push('', tenantName + ' has no venues open for booking right now.');
for (const venue of venues) {
  facts.push(
    '',
    '## ' + venue.name + ' (venueId ' + venue.id + ')',
    'Address: ' + venue.address,
    'Phone: ' + localPhone(venue.phone),
    'Open: ' + hoursOf(venue),
    'Paying: ' + paymentOf(venue),
    'Cancelling: customers can cancel a booking themselves ' +
      (venue.cancellationCutOffHours === 0 ? 'until it starts.' : 'up to ' + durationOf(venue.cancellationCutOffHours * 60) + ' before it starts.'),
  );
  const venueResources = resources.filter((r) => r.venueId === venue.id);
  if (venueResources.length > 0) facts.push('Resources (booked by the slot):');
  for (const resource of venueResources) {
    const rules = priceRules
      .filter((rule) => rule.resourceId === resource.id)
      .map((rule) => dayList(rule.weekdays) + ' ' + clock(rule.startTime) + ' to ' + clock(rule.endTime) + ': ' + money(rule.price));
    facts.push(
      '• ' + resource.name + ' (resourceId ' + resource.id + '): ' + SPORTS[resource.type] + ' (type ' + resource.type + '), ' +
        resource.slotMinutes + '-minute slots, starting every ' + resource.startIntervalMinutes + ' minutes. ' +
        money(resource.price) + ' per slot' + (rules.length > 0 ? ', except ' + rules.join('; ') : '') + '.',
    );
  }
  const venuePlans = venue.hasGym ? plans.filter((plan) => plan.venueId === venue.id) : [];
  if (venuePlans.length > 0) {
    facts.push('Gym Membership Plans:');
    for (const plan of venuePlans) facts.push('• ' + plan.name + ': ' + lengthOf(plan) + ', ' + money(plan.price) + '.');
  }
}
if (LISTS.some((node) => $(node).item.json.data.totalElements > $(node).item.json.data.content.length)) {
  facts.push('', 'Not everything fit in this list. For anything missing, give the way to reach a person.');
}

// AST-06: how to reach a person, finishing a sentence that starts with "please".
let callVenue;
if (venues.length === 0) callVenue = 'contact ' + tenantName + ' directly.';
else if (venues.length === 1) callVenue = 'call ' + venues[0].name + ' on ' + localPhone(venues[0].phone) + '.';
else callVenue = 'call one of our venues:\n' + venues.map((v) => '• ' + v.name + ': ' + localPhone(v.phone)).join('\n');

// The tools name resources and venues from this, in each venue's time zone.
const venueById = Object.fromEntries(
  venues.map((v) => [
    v.id,
    { name: v.name, timeZone: v.timeZone, phone: localPhone(v.phone), payAtVenue: v.payAtVenue, advancePercent: v.advancePercent, paymentTimeLimitMinutes: v.paymentTimeLimitMinutes },
  ]),
);
const names = {
  venues: venueById,
  resources: Object.fromEntries(resources.map((r) => [r.id, { name: r.name, venueId: r.venueId, slotMinutes: r.slotMinutes }])),
};

const SENT_WORDS = { image: 'a photo', document: 'a file', audio: 'a voice note', video: 'a video', sticker: 'a sticker' };
const agentInput = message.text || '[The customer sent ' + (SENT_WORDS[message.type] ?? 'a ' + message.type + ' message') + ' with no text]';

return {
  json: {
    ...message,
    tenantId,
    tenantName,
    sessionId: tenantId + ':' + message.phone,
    customer,
    customerKnown: customer !== null,
    callVenue,
    facts: facts.join('\n'),
    names: JSON.stringify(names),
    agentInput,
  },
};

