// The agent answers {"reply","choices","listButton","customerName"}. Anything else is never sent, since it may be the AI's own notes.
// A Chat Offer made in this message, or asked about again ("confirmOffer"), gets its own choices: Yes and No (D-47),
// or for a receipt of several, what it may pay for (T38).
// Limits are WhatsApp's, for reply buttons, list rows and the text above them.
const MAX_BUTTONS = 3;
const MAX_LIST_ROWS = 10;
const BUTTON_TITLE_LIMIT = 20;
const ROW_TITLE_LIMIT = 24;
const LIST_BUTTON_LIMIT = 20;
const INTERACTIVE_BODY_LIMIT = 1024;
const TEXT_LIMIT = 4096;
const NAME_LIMIT = 80;
const DEFAULT_LIST_BUTTON = 'Choose';
const DEFAULT_OFFER_CHOICES = ['Yes', 'No'];
const FOOTER_LIMIT = 60;

const gather = $('Gather').item.json;
const raw = $('Assistant Agent').item.json.output ?? '';
const waiting = $json.id ? $json : null;
const { detailsBlock, doneLine } = $('Word Outcome').item.json;
let answer;
if (raw && typeof raw === 'object') answer = raw;
else {
  let text = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  try {
    answer = JSON.parse(text);
  } catch {
    answer = null;
  }
}
if (!answer || typeof answer !== 'object') answer = {};

const replied = typeof answer.reply === 'string' && answer.reply.trim() !== '';
let reply;
if (replied) reply = detailsBlock ? answer.reply.trim() + '\n\n' + detailsBlock : answer.reply.trim();
else if (detailsBlock) reply = doneLine + '\n\n' + detailsBlock + '\n\nFor anything else, please ' + gather.callVenue;
else reply = 'Sorry, something went wrong on our side. Please ' + gather.callVenue;
const clip = (text, limit) => (text.length > limit ? text.slice(0, limit - 1).trimEnd() + '…' : text);

const given = replied && Array.isArray(answer.choices)
  ? answer.choices.filter((c) => typeof c === 'string' && c.trim() !== '').map((c) => c.trim())
  : [];
const askedOffer = replied && waiting && (waiting.isNew || answer.confirmOffer === true) ? waiting : null;
const receiptOffer = askedOffer?.kind === 'receipt' && askedOffer.details.options.length > 1 ? askedOffer : null;
let labels = given;
if (receiptOffer) labels = receiptOffer.details.options.map((o) => o.label);
else if (askedOffer && given.length !== DEFAULT_OFFER_CHOICES.length) labels = DEFAULT_OFFER_CHOICES;
const idOf = (i) => {
  if (receiptOffer) return 'offer-pick-' + receiptOffer.id + '-' + (i + 1);
  return askedOffer ? 'offer-' + ['yes', 'no'][i] + '-' + askedOffer.id : 'choice-' + (i + 1);
};
const asButtons = labels.length <= MAX_BUTTONS;
const clipped = labels.slice(0, MAX_LIST_ROWS).map((c) => clip(c, asButtons ? BUTTON_TITLE_LIMIT : ROW_TITLE_LIMIT));
// An offer's choices keep their places, since each id points at one of them.
const titles = askedOffer ? clipped : [...new Set(clipped)];
const footer = askedOffer ? { text: clip(askedOffer.details.footer, FOOTER_LIMIT) } : null;

let message;
if (titles.length === 0 || reply.length > INTERACTIVE_BODY_LIMIT) {
  message = { type: 'text', text: { preview_url: false, body: clip(reply, TEXT_LIMIT) } };
} else if (asButtons) {
  message = {
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: reply },
      action: { buttons: titles.map((title, i) => ({ type: 'reply', reply: { id: idOf(i), title } })) },
    },
  };
  if (footer) message.interactive.footer = footer;
} else {
  const listButton = typeof answer.listButton === 'string' && answer.listButton.trim() !== '' ? answer.listButton.trim() : DEFAULT_LIST_BUTTON;
  message = {
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: reply },
      action: {
        button: clip(listButton, LIST_BUTTON_LIMIT),
        sections: [{ rows: titles.map((title, i) => ({ id: idOf(i), title })) }],
      },
    },
  };
  if (footer) message.interactive.footer = footer;
}

// AST-05: only a new number's own name is saved, once.
const name = typeof answer.customerName === 'string' ? answer.customerName.trim().replace(/\s+/g, ' ') : '';
const offeredName = waiting?.isNew ? waiting.details.customerName ?? '' : '';
const customerName = gather.customer === null ? [name, offeredName].find((n) => n !== '' && n.length <= NAME_LIMIT) ?? null : null;

return { json: { message, customerName } };

// A booking or receipt done in this message still reaches the customer, with its details, when the reply fails.
const gather = $('Gather').item.json;
const { detailsBlock, doneLine } = $('Word Outcome').isExecuted ? $('Word Outcome').item.json : { detailsBlock: '' };
const body = detailsBlock
  ? doneLine + '\n\n' + detailsBlock + '\n\nFor anything else, please ' + gather.callVenue
  : 'Sorry, something went wrong on our side. Please ' + gather.callVenue;
return { json: { message: { type: 'text', text: { preview_url: false, body } } } };

// D-47: what this message does. A photo or PDF is a receipt (T38); a tap is exact; typed words go by Offer Check.
const OFFER_TAP = /^offer-(yes|no|pick)-(\d+)(?:-(\d+))?$/;
const gather = $('Gather').item.json;
const found = $('Find Offer').item.json;
const offer = found.id ? found : null;
const tap = OFFER_TAP.exec(String(gather.tapId ?? ''));
// A receipt Chat Offer of several is answered by picking one; the others, by yes or no.
const options = offer?.kind === 'receipt' ? offer.details.options.length : 0;
const picks = options > 1 ? options : 0;
const pickOf = (n) => (Number.isInteger(n) && n >= 1 && n <= picks ? n - 1 : null);

let decision = 'none';
let pick = null;
if (gather.receiptMediaId) decision = 'receipt';
else if (tap) {
  if (!offer) decision = 'gone';
  else if (Number(tap[2]) !== offer.id) decision = 'stale';
  else if (tap[1] === 'pick') {
    pick = pickOf(Number(tap[3]));
    decision = pick === null ? 'other' : 'pick';
  } else decision = picks ? 'other' : tap[1];
} else if (offer) {
  const said = $('Offer Check').isExecuted ? String($('Offer Check').item.json.text ?? '') : '';
  const word = said.toUpperCase().match(/[A-Z]+|\d+/)?.[0];
  if (picks) {
    pick = pickOf(Number(word));
    decision = pick !== null ? 'pick' : word === 'NO' ? 'no' : 'other';
  } else decision = word === 'YES' ? 'yes' : word === 'NO' ? 'no' : 'other';
}
return { json: { decision, offer, pick } };

