// What the agent is told about the Chat Offer or receipt, and the exact details added below its reply.
const CENTS_PER_RUPEE = 100;
const DEFAULT_TIME_ZONE = 'Asia/Colombo';

const gather = $('Gather').item.json;
const names = JSON.parse(gather.names);
const { decision, offer } = $('Decide').item.json;
const taken = $('Take Offer').isExecuted && $('Take Offer').item.json.id ? $('Take Offer').item.json : null;
const api = $('Book').isExecuted ? $('Book').item.json : $('Cancel Booking').isExecuted ? $('Cancel Booking').item.json : null;

const money = (m) => m.currency + ' ' + (m.amount / CENTS_PER_RUPEE).toLocaleString('en-US', { maximumFractionDigits: 2 });
const zoneOf = (venueId) => names.venues[venueId]?.timeZone ?? DEFAULT_TIME_ZONE;
const time = (iso, zone) => new Date(iso).toLocaleTimeString('en-GB', { timeZone: zone, hour: 'numeric', minute: '2-digit', hour12: true });
const shortDay = (iso, zone) => new Date(iso).toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' });
const sameDay = (a, b, zone) => shortDay(a, zone) === shortDay(b, zone);

const reach = 'give the way to reach a person';
let news;
let detailsBlock = '';
let doneLine = '';

function bookingBlock(booking) {
  const zone = zoneOf(booking.venueId);
  const resource = names.resources[booking.resourceId];
  const venue = names.venues[booking.venueId];
  const lines = [
    '*' + (resource?.name ?? 'Booking') + (venue ? ', ' + venue.name : '') + '*',
    shortDay(booking.startsAt, zone) + ', ' + time(booking.startsAt, zone) + ' – ' + time(booking.endsAt, zone),
  ];
  if (booking.status === 'AWAITING_PAYMENT' && booking.expiresAt) {
    const today = sameDay(booking.expiresAt, new Date().toISOString(), zone);
    const by = time(booking.expiresAt, zone) + (today ? ' today' : ', ' + shortDay(booking.expiresAt, zone));
    lines.push('Pay *' + money(booking.amountDue) + '* by ' + by);
    const bank = booking.bankAccount;
    if (bank) lines.push(bank.bankName + (bank.branch ? ', ' + bank.branch : ''), bank.accountName, bank.accountNumber);
  } else {
    lines.push('Confirmed · ' + money(booking.price) + ' to pay at the venue');
  }
  return lines.join('\n');
}

function afterBooking() {
  const { statusCode, body } = api;
  if (api.error || !body || statusCode >= 500) {
    return 'The customer said yes, but booking failed for a technical reason, so NOTHING was booked. Say sorry, that you can\'t book right now, and ' + reach + '.';
  }
  if (statusCode < 300) {
    const booking = body.data;
    detailsBlock = bookingBlock(booking);
    doneLine = 'Booked ✅';
    if (booking.status === 'AWAITING_PAYMENT') {
      return 'Just done: the customer said yes and the booking was made (' + taken.details.summary + '). It waits for payment: ' +
        money(booking.amountDue) + ' by bank transfer before the time shown below your reply, or it expires. ' +
        'The booking, amount, time limit and bank account are added below your reply word for word, so don\'t repeat the account details. ' +
        'Tell them it\'s booked and held for them until then, but not confirmed until the venue accepts their payment; to transfer the amount by that time and then send a photo or screenshot of the Transfer Receipt here in this chat.';
    }
    return 'Just done: the customer said yes and the booking was made and confirmed (' + taken.details.summary + '). The venue is Pay at Venue: nothing to pay now, they pay at the venue. The booking is added below your reply.';
  }
  const why = body.message ?? 'refused';
  switch (body.code) {
    case 'tt_bkg_002':
      return 'The customer said yes, but NOTHING was booked: someone else just took that time (' + taken.details.summary + '). Say sorry, use find_free_times for the same date near that time, and offer the nearest free times as choices.';
    case 'tt_bkg_012':
      return 'The customer said yes, but NOTHING was booked: the price changed (' + why + '). Tell them the new price and, if they still want it, call offer_booking again so they can confirm the new price.';
    case 'tt_bkg_003':
      return 'The customer said yes, but NOTHING was booked: they already have a booking waiting for payment. They pay for it first, or cancel it (my_bookings, then offer_cancel).';
    case 'tt_bkg_005':
      return 'The customer said yes, but NOTHING was booked: their name isn\'t saved yet. Ask for their name; then make the Chat Offer again.';
    default:
      return 'The customer said yes, but NOTHING was booked: ' + why + '. Explain kindly and offer to look for another time.';
  }
}

function afterCancelling() {
  const { statusCode, body } = api;
  if (api.error || !body || statusCode >= 500) {
    return 'The customer said yes, but cancelling failed for a technical reason, so the booking is NOT cancelled. Say sorry and ' + reach + '.';
  }
  if (statusCode < 300) {
    const booking = body.data;
    const refund = booking.paid.amount > 0 ? ' They had paid ' + money(booking.paid) + '; a refund is up to the venue, so give the venue\'s phone for it.' : '';
    return 'Just done: the customer said yes and the booking is cancelled (' + taken.details.summary.replace(/^cancel /, '') + '). The time is free again.' + refund;
  }
  return 'The customer said yes, but the booking is NOT cancelled: ' + (body.message ?? 'refused') + '. Explain kindly; if a phone number is given, pass it on.';
}

const listOf = (options) => options.map((o, i) => (i + 1) + '. ' + o.summary).join('\n');
const isReceiptOf = (o) => o.kind === 'receipt' && o.details.options.length === 1;
const waitingNow = (o) => {
  if (isReceiptOf(o)) return 'A Chat Offer is waiting: the customer sent a photo or file and was asked whether it is the Transfer Receipt for ' + o.details.options[0].summary + '.';
  if (o.kind === 'receipt') return 'A Chat Offer is waiting: the customer sent a photo or file of a Transfer Receipt and was asked which of these it pays for:\n' + listOf(o.details.options) + '\n';
  return 'A Chat Offer is waiting for the customer\'s yes: ' + o.details.summary + '.';
};

// T38: the photo or file went to the API as a Transfer Receipt, or why it didn't.
function afterReceipt() {
  const target = $('Receipt Target').item.json;
  const info = $('Media Info').item.json;
  const upload = $('Upload Receipt').isExecuted ? $('Upload Receipt').item.json : null;
  const sent = $('Send Receipt').isExecuted ? $('Send Receipt').item.json : null;
  const notSent = 'The receipt is NOT sent (it was for ' + target.summary + '): ';
  const technical = notSent + 'it couldn\'t be fetched or saved for a technical reason. Say sorry, ask them to send it again in a few minutes, and ' + reach + '.';
  const why = (body) => (body.errors ?? []).map((e) => e.message).join('; ') || body.message || 'refused';
  if (info.error || typeof info.url !== 'string') return technical;
  if (!$('Download Media').isExecuted) return notSent + 'the file is over 5 MB. Ask for a screenshot of the transfer instead.';
  if (!upload || upload.error || !upload.body || upload.statusCode >= 500) return technical;
  if (upload.statusCode >= 400) {
    return notSent + 'the file can\'t be used (' + why(upload.body) + '). Ask for a photo or screenshot of the transfer, or a PDF, of at most 5 MB.';
  }
  if (!sent || sent.error || !sent.body || sent.statusCode >= 500) return technical;
  if (sent.statusCode < 300) {
    detailsBlock = target.block;
    doneLine = 'Receipt sent ✅';
    return 'Just done: the photo or file the customer sent went to the venue as the Transfer Receipt for ' + target.summary + '. ' +
      'The venue checks it next; while it waits for that check it won\'t expire, and the customer gets a WhatsApp message once it\'s accepted. ' +
      'Tell them so in a line or two. What it was sent for is added below your reply, so don\'t repeat it.';
  }
  if (sent.body.code === 'tt_pay_010') {
    return notSent + 'it no longer waits for payment: a receipt was already sent for it, or it was cancelled. Check my_bookings or my_memberships and tell them where it stands.';
  }
  return notSent + why(sent.body) + ' Explain kindly; for a booking, offer to look for free times again.';
}

function afterPhoto() {
  const { failed, waiting } = $('List Waiting').item.json;
  if (failed) {
    return 'The customer sent a photo or file, but TurfTap couldn\'t check what waits for payment, so NOTHING was sent. Say sorry, ask them to send it again in a few minutes, and ' + reach + '.';
  }
  if (waiting.length === 0) {
    return 'The customer sent a photo or file. TurfTap takes these as Transfer Receipts, but nothing of theirs waits for payment, so it was NOT sent anywhere. ' +
      'Check my_bookings and my_memberships: if one says "receipt sent", tell them the venue already has their receipt and is checking it; otherwise say there is nothing to pay for right now. ' +
      'If their message shows it\'s a photo of something else, say you can only take Transfer Receipts here, and ' + reach + '.';
  }
  if (waiting.length > 1) {
    return 'The customer sent a photo or file of a Transfer Receipt, and several things wait for payment:\n' + listOf(waiting) + '\n' +
      'Ask which one it\'s for, naming each briefly. TurfTap adds them below your reply as choices to tap, so give no choices yourself. Nothing is sent until they pick one.';
  }
  return 'The customer sent a photo or file. One thing waits for payment: ' + waiting[0].summary + '. ' +
    'Ask whether this is their Transfer Receipt for it, naming it briefly, with the yes label first and the no label second in "choices". Nothing is sent until they say yes.';
}

if (decision === 'none') news = 'No Chat Offer is waiting for the customer\'s yes.';
else if (decision === 'receipt') news = afterPhoto();
else if (decision === 'other' && isReceiptOf(offer)) {
  news = waitingNow(offer) + ' This message doesn\'t answer it. Answer what they asked, then ask again whether it\'s the receipt for it, with the Yes and No choices and "confirmOffer" true.';
} else if (decision === 'other' && offer.kind === 'receipt') {
  news = waitingNow(offer) + 'This message doesn\'t pick one. Answer what they asked, then ask again which one the receipt is for, with "confirmOffer" true; TurfTap adds the choices.';
} else if (decision === 'other') {
  news = waitingNow(offer) + ' This message doesn\'t accept it. If they want something changed, make a new Chat Offer with the change. ' +
    'If they asked something, answer and then ask again about the offer, with the Yes and No choices.';
} else if (decision === 'stale') {
  news = 'The customer tapped a button of an older Chat Offer that was replaced, so nothing was done. ' + waitingNow(offer) + ' Ask about this one.';
} else if (decision === 'gone' || !taken) {
  news = 'The customer answered a Chat Offer that ran out or was already used, so nothing was done this time. Check my_bookings before saying what they have, and offer again if they still want it. ' +
    'If they were picking what a receipt photo is for, ask them to send the photo again.';
} else if (decision === 'no' && isReceiptOf(taken)) {
  news = 'The customer said the photo or file is not the Transfer Receipt for ' + taken.details.options[0].summary + ', so it was NOT sent. ' +
    'Ask what they\'d like; if they meant to send the receipt, they can send the right photo here.';
} else if (decision === 'no' && taken.kind === 'receipt') {
  news = 'The customer said the receipt photo is for none of the things waiting for payment, so it was NOT sent. Ask what it\'s for; if it\'s something you can\'t handle, ' + reach + '.';
} else if (decision === 'no') {
  news = 'The customer said no to the Chat Offer (' + taken.details.summary + '), so it\'s dropped and nothing changed. Ask what they\'d like instead.';
} else if (taken.kind === 'book') news = afterBooking();
else if (taken.kind === 'cancel') news = afterCancelling();
else if (taken.kind === 'receipt') news = afterReceipt();
else news = 'The customer said yes to a Chat Offer this Assistant can\'t carry out, so nothing changed. Say sorry and ' + reach + '.';

return { json: { offerNews: news, detailsBlock, doneLine } };

// T38: what a receipt photo could pay for. One past its Payment Time Limit no longer counts.
const CENTS_PER_RUPEE = 100;
const DEFAULT_TIME_ZONE = 'Asia/Colombo';
const LABEL_LIMIT = 20; // a WhatsApp reply button's title

const names = JSON.parse($('Gather').item.json.names);
const lists = [$('Find Waiting Bookings').item.json, $json];
if (lists.some((r) => r.error || !r.body || r.statusCode >= 400)) return { json: { failed: true, waiting: [] } };
const [bookings, memberships] = lists.map((r) => r.body.data.content);

const money = (m) => m.currency + ' ' + (m.amount / CENTS_PER_RUPEE).toLocaleString('en-US', { maximumFractionDigits: 2 });
const zoneOf = (venueId) => names.venues[venueId]?.timeZone ?? DEFAULT_TIME_ZONE;
const time = (iso, zone) => new Date(iso).toLocaleTimeString('en-GB', { timeZone: zone, hour: 'numeric', minute: '2-digit', hour12: true });
const shortDay = (iso, zone) => new Date(iso).toLocaleDateString('en-GB', { timeZone: zone, weekday: 'short', day: 'numeric', month: 'short' });
const localDay = (isoDate) => shortDay(isoDate + 'T12:00:00Z', 'UTC');
const clip = (text) => (text.length > LABEL_LIMIT ? text.slice(0, LABEL_LIMIT - 1).trimEnd() + '…' : text);
const sentLine = (m) => 'Receipt for *' + money(m) + '* sent · the venue checks it next';
const now = Date.now();
const inTime = (item) => item.expiresAt === null || new Date(item.expiresAt).getTime() > now;

const fromBookings = bookings.filter(inTime).map((b) => {
  const zone = zoneOf(b.venueId);
  const what = (names.resources[b.resourceId]?.name ?? 'Booking') + ', ' + (names.venues[b.venueId]?.name ?? 'a venue');
  const when = shortDay(b.startsAt, zone) + ', ' + time(b.startsAt, zone) + ' – ' + time(b.endsAt, zone);
  return {
    bookingId: b.id,
    createdAt: b.createdAt,
    label: shortDay(b.startsAt, zone) + ' ' + time(b.startsAt, zone),
    summary: 'the booking of ' + what + ', ' + when + ', ' + money(b.amountDue) + ' due',
    block: ['*' + what + '*', when, sentLine(b.amountDue)].join('\n'),
  };
});
const fromMemberships = memberships.filter(inTime).map((m) => {
  const what = m.planName + ', ' + (names.venues[m.venueId]?.name ?? 'a venue');
  const when = localDay(m.startsOn) + (m.endsOn === m.startsOn ? '' : ' – ' + localDay(m.endsOn));
  return {
    membershipId: m.id,
    createdAt: m.createdAt,
    label: m.planName,
    summary: 'the ' + m.planName + ' membership at ' + (names.venues[m.venueId]?.name ?? 'a venue') + ', ' + when + ', ' + money(m.amountDue) + ' due',
    block: ['*' + what + '*', when, sentLine(m.amountDue)].join('\n'),
  };
});

// Each label is a tap target, so two that read the same get their number added.
const waiting = [...fromBookings, ...fromMemberships].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
const labels = waiting.map((w) => clip(w.label));
const options = waiting.map(({ createdAt, ...w }, i) => ({
  ...w,
  label: labels.filter((l) => l === labels[i]).length > 1 ? clip((i + 1) + '. ' + w.label) : labels[i],
}));
return { json: { failed: false, waiting: options } };

// The receipt and what it pays for, from the receipt Chat Offer the customer answered: its one option, or their pick.
const { details } = $json;
const option = details.options[$('Decide').item.json.pick ?? 0];
const target = option.bookingId ? { bookingId: option.bookingId } : { membershipId: option.membershipId };
return { json: { mediaId: details.mediaId, target, summary: option.summary, block: option.block } };
